'use strict';

// A detached flight still settles its original callers. The registry tracks
// only flights available for subsequent readers of each key.
function createFlights() {
  const pending = new Map();

  return {
    run(key, work, commit) {
      if (pending.has(key)) return pending.get(key);
      // Only the flight still registered for key may commit or unregister;
      // forget/clear (or a newer flight) make this one obsolete.
      const release = () => {
        if (pending.get(key) !== promise) return false;
        pending.delete(key);
        return true;
      };
      const promise = Promise.resolve().then(work).then(value => {
        if (release()) commit(value);
        return value;
      }, reason => {
        release();
        throw reason;
      });
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

module.exports = { createFlights };

