'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

(async () => {
  // newer flight not detached by older completion; dedup preserved
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.invalidate('k');
    const b1 = c.get('k'); await tick();
    gates[0].resolve('old'); assert.equal(await a, 'old');
    const b2 = c.get('k'); assert.equal(calls, 2, 'joins newer flight');
    gates[1].resolve('new'); assert.equal(await b1, 'new'); assert.equal(await b2, 'new');
    assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
  }
  // set wins over earlier load; TTL not restarted
  {
    let t = 0; const g = deferred(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (calls++ === 0 ? g.promise : 'L') });
    const a = c.get('k'); await tick(); c.set('k', 'S');
    t = 5; g.resolve('old'); assert.equal(await a, 'old');
    assert.equal(await c.get('k'), 'S');
    t = 10; assert.equal(c.size, 0); assert.equal(await c.get('k'), 'L'); assert.equal(calls, 2);
  }
  // rejection not cached, same reason to all waiters, retry works; sync throw
  {
    let calls = 0; const reason = { nonError: true };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const p1 = c.get('k'), p2 = c.get('k');
    await assert.rejects(p1, r => r === reason); await assert.rejects(p2, r => r === reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // obsolete rejection does not detach newer flight
  {
    const gates = [deferred(), deferred()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick(); c.clear(); const b = c.get('k'); await tick();
    gates[0].reject(new Error('x')); await assert.rejects(a);
    c.get('k'); assert.equal(calls, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v');
  }
  // load calls invalidate synchronously -> its value not stored; reading own key joins
  {
    let calls = 0; let self;
    const c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) { self = c.get(k); c.invalidate(k); return 'first'; } return 'second'; } });
    assert.equal(await c.get('k'), 'first'); assert.equal(await self, 'first');
    assert.equal(await c.get('k'), 'second'); assert.equal(calls, 2);
  }
  // ttl 0: dedup unsettled, no reuse
  {
    let calls = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    const [x, y] = await Promise.all([c.get('k'), c.get('k')]); assert.equal(x, 1); assert.equal(y, 1);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  console.log('all scratch checks passed');
})().catch(e => { console.error(e); process.exit(1); });
